patches.diff:
From d646687c4b4eab4d1b2ed789d4cb966e098755d4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:04:30 +0100
Subject: [PATCH] applets/digital-clock: add option to show time zones as city
 and code

The time zone could only be shown as a code, a city or a UTC offset, so
one had to pick between a recognizable name and the short code. Add a
"City and code" format that shows both, for example "London (GMT)".

BUG: 432648
---
 applets/digital-clock/CalendarView.qml     |  4 ++++
 applets/digital-clock/DigitalClock.qml     | 10 ++++++++--
 applets/digital-clock/Tooltip.qml          |  4 ++++
 applets/digital-clock/configAppearance.qml |  1 +
 applets/digital-clock/main.xml             |  3 ++-
 5 files changed, 19 insertions(+), 3 deletions(-)

diff --git a/applets/digital-clock/CalendarView.qml b/applets/digital-clock/CalendarView.qml
index 48d5dcccb7..9e7cdc392a 100644
--- a/applets/digital-clock/CalendarView.qml
+++ b/applets/digital-clock/CalendarView.qml
@@ -508,6 +508,10 @@ PlasmaExtras.Representation {
                             return TimeZonesI18n.i18nCity(tzClock.timeZone);
                         case 2: // Offset from UTC time
                             return tzClock.timeZoneOffset;
+                        case 3: { // City and code
+                            const city = TimeZonesI18n.i18nCity(tzClock.timeZone);
+                            return city === tzClock.timeZoneCode ? city : i18nc("@label %1 is a city, %2 is a time zone code", "%1 (%2)", city, tzClock.timeZoneCode);
+                        }
                         }
                     }

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..377affffc1 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -560,7 +560,7 @@ MouseArea {
         let timezoneString = "";

         if (showTimezone) {
-            // format time zone as tz code, city or UTC offset
+            // format time zone as tz code, city, UTC offset or city with tz code
             switch (Plasmoid.configuration.displayTimezoneFormat) {
             case 0: // Code
                 timezoneString = clock.timeZoneCode;
@@ -571,8 +571,14 @@ MouseArea {
             case 2: // Offset from UTC time
                 timezoneString = clock.timeZoneOffset;
                 break;
+            case 3: { // City and code
+                const city = TimeZonesI18n.i18nCity(clock.timeZone);
+                timezoneString = city === clock.timeZoneCode ? city : i18nc("@label %1 is a city, %2 is a time zone code", "%1 (%2)", city, clock.timeZoneCode);
+                break;
+            }
             }
-            if ((Plasmoid.configuration.showDate || oneLineMode) && Plasmoid.formFactor === PlasmaCore.Types.Horizontal) {
+            if ((Plasmoid.configuration.showDate || oneLineMode) && Plasmoid.formFactor === PlasmaCore.Types.Horizontal
+                && Plasmoid.configuration.displayTimezoneFormat !== 3) {
                 timezoneString = `(${timezoneString})`;
             }
         }
diff --git a/applets/digital-clock/Tooltip.qml b/applets/digital-clock/Tooltip.qml
index 7ecafd0baf..b28da20b8e 100644
--- a/applets/digital-clock/Tooltip.qml
+++ b/applets/digital-clock/Tooltip.qml
@@ -142,6 +142,10 @@ Item {
                             return TimeZonesI18n.i18nCity(tzClock.timeZone);
                         case 2: // Offset from UTC time
                             return tzClock.timeZoneOffset;
+                        case 3: { // City and code
+                            const city = TimeZonesI18n.i18nCity(tzClock.timeZone);
+                            return city === tzClock.timeZoneCode ? city : i18nc("@label %1 is a city, %2 is a time zone code", "%1 (%2)", city, tzClock.timeZoneCode);
+                        }
                         }
                     }

diff --git a/applets/digital-clock/configAppearance.qml b/applets/digital-clock/configAppearance.qml
index bcab974d18..cf0ff51f20 100644
--- a/applets/digital-clock/configAppearance.qml
+++ b/applets/digital-clock/configAppearance.qml
@@ -131,6 +131,7 @@ KCMUtils.SimpleKCM {
                     i18n("Code"),
                     i18n("City"),
                     i18n("Offset from UTC time"),
+                    i18n("City and code"),
                 ]
                 onActivated: appearancePage.cfg_displayTimezoneFormat = currentIndex
             }
diff --git a/applets/digital-clock/main.xml b/applets/digital-clock/main.xml
index 6716b906c5..805b472eb1 100644
--- a/applets/digital-clock/main.xml
+++ b/applets/digital-clock/main.xml
@@ -75,11 +75,12 @@
       <default>false</default>
     </entry>
     <entry name="displayTimezoneFormat" type="Enum">
-      <label>Whether the time zone is displayed as a code i.e. "GMT", full text i.e. "London" or UTC offset "+1".</label>
+      <label>Whether the time zone is displayed as a code i.e. "GMT", full text i.e. "London", UTC offset "+1" or full text with code i.e. "London (GMT)".</label>
       <choices name="Settings::displayTimezoneFormat">
         <choice name="Code" />
         <choice name="FullText" />
         <choice name="UTCOffset" />
+        <choice name="FullTextAndCode" />
       </choices>
       <default>0</default>
     </entry>
-- 
